import React from 'react';
import Button from '../components/ui/Button';
import Card from '../components/ui/Card';
import Table from '../components/ui/Table';
import { getApi, deleteApi } from '../ults/api';
import { Product } from '../types';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import Swal, { SweetAlertResult } from 'sweetalert2';

const Products: React.FC = () => {
    const navigate = useNavigate();
    const queryClient = useQueryClient();

    // Function GET Products
    const getProducts = () => getApi<Product[]>(`${process.env.REACT_APP_API_URL}/api/products`);

    // Lấy dữ liệu từ React Query
    const { data: products, isLoading } = useQuery({
        queryKey: ['Products'],
        queryFn: getProducts,
    });

    // Hàm gọi API xoá
    const deleteProduct = async (id: string | number) => {
        return deleteApi(`${process.env.REACT_APP_API_URL}/api/products/delete/${id}`);
    };

    // Mutation xoá sản phẩm
    const { mutate: handleDelete } = useMutation({
        mutationFn: deleteProduct,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['Products'] });
            Swal.fire('Deleted!', 'Product has been deleted.', 'success');
        },
        onError: () => {
            Swal.fire('Error!', 'Failed to delete product.', 'error');
        },
    });

    // Hàm xác nhận xoá
    const confirmDelete = (id: string | number) => {
        Swal.fire({
            title: 'Are you sure?',
            text: 'This action cannot be undone!',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#3085d6',
            cancelButtonColor: '#d33',
            confirmButtonText: 'Yes, delete it!',
        }).then((result: SweetAlertResult) => {
            if (result.isConfirmed) {
                handleDelete(id);
            }
        });
    };

    // Định nghĩa giao diện bảng Products
    const columns = [
        {
            key: 'id',
            title: 'User ID',
            render: (value: string) => (
                <span className="font-mono text-sm text-primary-600">#{value}</span>
            ),
        },
        {
            key: 'avatar',
            title: 'Avatar',
            render: (value: string, item: Product) => (
                <div className="flex items-center">
                    {item.avatar ? (
                        <img src={item.avatar} alt={item.name} className="w-10 h-10 rounded-full" />
                    ) : (
                        <div className="w-10 h-10 bg-primary-100 rounded-full flex items-center justify-center">
                            <span className="text-sm font-medium text-primary-700">
                                {item.name.charAt(0)}
                            </span>
                        </div>
                    )}
                </div>
            ),
        },
        {
            key: 'sku',
            title: 'SKU',
            render: (value: string) => (
                <span className="font-mono text-sm text-primary-600">{value}</span>
            ),
        },
        {
            key: 'name',
            title: 'Product name',
            render: (value: string) => (
                <div>
                    <p className="font-medium text-gray-600">{value}</p>
                </div>
            ),
        },
        {
            key: 'unit_of_measure',
            title: 'Unit of measure',
            render: (value: string) => (
                <div>
                    <p className="font-medium text-gray-600">{value}</p>
                </div>
            ),
        },
        {
            key: 'price',
            title: 'Price',
            render: (value: string) => (
                <div>
                    <p className="font-medium text-gray-600">{value}</p>
                </div>
            ),
        },
        {
            key: 'actions',
            title: 'Actions',
            render: (value: any, item: Product) => (
                <div className="flex items-center space-x-2">
                    <Button size="sm" variant="outline">
                        Modify
                    </Button>
                    <Button size="sm" variant="outline">
                        Details
                    </Button>
                    <Button
                        size="sm"
                        variant="outline"
                        className="text-red-600 border-red-600 hover:bg-red-50"
                        onClick={() => confirmDelete(item.id)}
                    >
                        Delete
                    </Button>
                </div>
            ),
        },
    ];

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Products</h1>
                    <p className="text-gray-600">Manage your products</p>
                </div>
                <div className="flex items-center gap-2">
                    <Button onClick={() => navigate('/admin/products/create')}>Create Product</Button>
                    <Button variant="outline">Export Report</Button>
                </div>
            </div>

            {/* Products Table */}
            <Card>
                <Table
                    data={products || []}
                    columns={columns}
                    loading={isLoading}
                    emptyMessage="No products found"
                />
            </Card>
        </div>
    );
};

export default Products;
