import React from 'react';
import { Routes, Route } from 'react-router-dom';
import { QueryClientProvider } from '@tanstack/react-query';
import { Toaster } from 'react-hot-toast';
import { queryClient } from './lib/queryClient';
import { TOAST_CONFIG } from './constants';
import Dashboard from './pages/Dashboard';
import Products from './pages/Products';
import Orders from './pages/Orders';
import Analytics from './pages/Analytics';
import Branches from './pages/Branches';
import Inventories from './pages/Inventories';
import OrderDetails from './pages/OrderDetails';
import NotFound from './pages/NotFound';
import Test from './pages/Test';
import Users from './pages/Users';
import CreateOrder from './pages/user/CreateOrder';
import AdminLayout from './components/layout/admin/AdminLayout';
import UserLayout from './components/layout/user/UserLayout';
import Home from './pages/user/Home';
import Categories from './pages/admin/Categories';
import BranchCreate from './pages/admin/BranchCreate';
import UploadPage from './pages/admin/UploadPage';
import ProductCreate from './pages/admin/ProductCreate';
import OrdersCreate from './pages/admin/OrdersCreate';

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <div className="min-w-[300px]">
        <Routes>
          <Route path="/admin" element={<AdminLayout />} >
            <Route index element={<Dashboard />} />
            <Route path="branches" element={<Branches />} />
            <Route path="branch-create" element={<BranchCreate />} />
            <Route path="products" element={<Products />} />
            <Route path="products/create" element={<ProductCreate />} />
            <Route path="orders" element={<Orders />} />
            <Route path="orders/create" element={<OrdersCreate />} />
            <Route path="orders/:id/products" element={<OrderDetails />} />
            <Route path="users" element={<Users />} />
            <Route path="categories" element={<Categories />} />
            <Route path="inventories" element={<Inventories />} />
            {/* <Route path="test" element={<Test />} /> */}
            <Route path="test" element={<Test />} />
            <Route path="analytics" element={<Analytics />} />
          </Route>
          <Route path="/" element={<UserLayout />} >
            <Route index element={<Home />} />
            <Route path="createOrder" element={<CreateOrder />} />
          </Route>
          <Route path="*" element={<NotFound />} />
        </Routes>
        
        {/* Global Toast Provider */}
        <Toaster
          position={TOAST_CONFIG.POSITION}
          toastOptions={{
            duration: TOAST_CONFIG.DURATION,
            style: {
              background: '#363636',
              color: '#fff',
            },
            success: {
              duration: 4000,
              iconTheme: {
                primary: '#10B981',
                secondary: '#fff',
              },
            },
            error: {
              duration: 5000,
              iconTheme: {
                primary: '#EF4444',
                secondary: '#fff',
              },
            },
          }}
        />
      </div>
    </QueryClientProvider>
  );
}

export default App;
