import axios, { AxiosRequestConfig, AxiosResponse } from 'axios';
import { API_CONFIG, ERROR_MESSAGES } from '../constants';
import { 
  Branch, 
  Product, 
  Order, 
  User, 
  Customer,
  DashboardStats, 
  ChartData, 
  ProductWithInventory,
  BranchFormData,
  ProductFormData,
  OrderCreateForm,
  UserFormData
} from '../types';

/**
 * Enhanced API Service with React Query integration
 * Centralized API calls with proper error handling and type safety
 */

// Create axios instance with default config
const apiClient = axios.create({
  baseURL: API_CONFIG.BASE_URL,
  timeout: API_CONFIG.TIMEOUT,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor for adding auth tokens, etc.
apiClient.interceptors.request.use(
  (config) => {
    // Add auth token if available
    const token = localStorage.getItem('authToken');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor for error handling
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    // Handle different types of errors
    if (error.response) {
      // Server responded with error status
      const { status, data } = error.response;
      
      switch (status) {
        case 401:
          // Unauthorized - redirect to login
          localStorage.removeItem('authToken');
          window.location.href = '/login';
          break;
        case 403:
          // Forbidden
          throw new Error(ERROR_MESSAGES.UNAUTHORIZED);
        case 404:
          // Not found
          throw new Error(ERROR_MESSAGES.NOT_FOUND);
        case 422:
          // Validation error
          throw new Error(data?.message || ERROR_MESSAGES.VALIDATION_ERROR);
        case 500:
          // Server error
          throw new Error(ERROR_MESSAGES.SERVER_ERROR);
        default:
          throw new Error(data?.message || ERROR_MESSAGES.UNKNOWN_ERROR);
      }
    } else if (error.request) {
      // Network error
      throw new Error(ERROR_MESSAGES.NETWORK_ERROR);
    } else {
      // Other error
      throw new Error(error.message || ERROR_MESSAGES.UNKNOWN_ERROR);
    }
  }
);

/**
 * Generic API methods
 */
export const api = {
  // GET request
  get: async <T>(url: string, config?: AxiosRequestConfig): Promise<T> => {
    const response: AxiosResponse<T> = await apiClient.get(url, config);
    return response.data;
  },

  // POST request
  post: async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
    const response: AxiosResponse<T> = await apiClient.post(url, data, config);
    return response.data;
  },

  // PUT request
  put: async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
    const response: AxiosResponse<T> = await apiClient.put(url, data, config);
    return response.data;
  },

  // PATCH request
  patch: async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
    const response: AxiosResponse<T> = await apiClient.patch(url, data, config);
    return response.data;
  },

  // DELETE request
  delete: async <T>(url: string, config?: AxiosRequestConfig): Promise<T> => {
    const response: AxiosResponse<T> = await apiClient.delete(url, config);
    return response.data;
  },
};

/**
 * Specific API endpoints
 */
export const apiEndpoints = {
  // Branches
  branches: {
    list: () => api.get<Branch[]>(`${process.env.REACT_APP_API_URL}/api/branches`),
    detail: (id: string) => api.get<Branch>(`/branches/${id}`),
    create: (data: BranchFormData) => api.post<Branch>('/branches', data),
    update: (id: string, data: Partial<BranchFormData>) => api.put<Branch>(`/branches/${id}`, data),
    delete: (id: string) => api.delete<void>(`/branches/${id}`),
  },

  // Products
  products: {
    list: (filters?: Record<string, any>) => api.get<Product[]>(`${process.env.REACT_APP_API_URL}/api/products`, { params: filters }),
    detail: (id: string) => api.get<Product>(`/products/${id}`),
    byBranch: (branchId: string) => api.get<ProductWithInventory[]>(`${process.env.REACT_APP_API_URL}/api/branches/${branchId}/products`),
    create: (data: ProductFormData) => api.post<Product>('/products', data),
    update: (id: string, data: Partial<ProductFormData>) => api.put<Product>(`/products/${id}`, data),
    delete: (id: string) => api.delete<void>(`/products/${id}`),
  },

  // Orders
  orders: {
    list: (filters?: Record<string, any>) => api.get<Order[]>('/orders', { params: filters }),
    detail: (id: string) => api.get<Order>(`/orders/${id}`),
    create: (data: OrderCreateForm) => api.post<Order>('/orders', data),
    update: (id: string, data: Partial<OrderCreateForm>) => api.put<Order>(`/orders/${id}`, data),
    updateStatus: (id: string, status: Order['status']) => api.patch<Order>(`/orders/${id}/status`, { status }),
    delete: (id: string) => api.delete<void>(`/orders/${id}`),
  },

  // Users/Customers
  users: {
    list: (filters?: Record<string, any>) => api.get<User[]>('/users', { params: filters }),
    detail: (id: string) => api.get<User>(`/users/${id}`),
    create: (data: UserFormData) => api.post<User>('/users', data),
    update: (id: string, data: Partial<UserFormData>) => api.put<User>(`/users/${id}`, data),
    delete: (id: string) => api.delete<void>(`/users/${id}`),
  },

  // Dashboard
  dashboard: {
    stats: () => api.get<DashboardStats>('/dashboard/stats'),
    revenueChart: () => api.get<ChartData>('/dashboard/revenue-chart'),
  },

  // Additional methods for compatibility
  getProductsByBranch: (branchId: string) => api.get<ProductWithInventory[]>(`/branches/${branchId}/products`),
  getDashboardStats: () => api.get<DashboardStats>('/dashboard/stats'),
  getRevenueChart: () => api.get<ChartData>('/dashboard/revenue-chart'),
  getCustomers: () => api.get<Customer[]>('/customers'),
} as const;

// Export types for use in other files
export type { Branch, Product, Order, User, DashboardStats, ChartData, ProductWithInventory } from '../types';
export type { BranchFormData, ProductFormData, OrderCreateForm, UserFormData } from '../types';