import React, { useEffect } from 'react';
import Modal from '../ui/Modal';
import Table from '../ui/Table';
import Button from '../ui/Button';
import Checkbox from '../ui/Checkbox';
import QuantityInput from '../ui/QuantityInput';
import { ProductWithInventory, OrderProductData } from '../../types';
import { useProductSelection } from '../../hooks';
import { formatCurrency } from '../../utils';

interface ProductSelectionModalProps {
  isOpen: boolean; // Trạng thái mở/đóng modal
  onClose: () => void; // Callback khi đóng modal
  branchId: string | null; // ID chi nhánh
  selectedProducts: OrderProductData[]; // Danh sách sản phẩm đã chọn trước đó
  onAddProducts: (products: OrderProductData[]) => void; // Callback khi thêm sản phẩm
}

const ProductSelectionModal: React.FC<ProductSelectionModalProps> = ({
  isOpen,
  onClose,
  branchId,
  selectedProducts,
  onAddProducts,
}) => {
  // Sử dụng hook custom để lấy sản phẩm theo chi nhánh và quản lý trạng thái chọn sản phẩm
  const {
    products,
    isLoading,
    selectedItems,
    selectedCount,
    totalItems,
    handleQuantityChange,
    handleAddSelected,
    initializeSelectedItems,
  } = useProductSelection(branchId, selectedProducts, onAddProducts);

  // Khi modal mở và dữ liệu sản phẩm load xong, khởi tạo selectedItems
  useEffect(() => {
    if (isOpen && products.length > 0) {
      initializeSelectedItems();
    }
  }, [isOpen, products, initializeSelectedItems]);

  /**
   * Xử lý thay đổi checkbox một sản phẩm
   * Nếu checked = true, đặt quantity mặc định = 1 nếu chưa có
   * Nếu unchecked, đặt quantity = 0 để xóa khỏi Map
   */
  const handleCheckboxChange = (productId: string, checked: boolean) => {
    const currentQuantity = selectedItems.get(productId) || 1;
    handleQuantityChange(productId, checked ? currentQuantity : 0);
  };

  /**
   * Xử lý checkbox "Chọn tất cả"
   * Nếu checked = true, đánh dấu tất cả sản phẩm hiện tại trong bảng
   * Nếu checked = false, bỏ chọn tất cả
   */
  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      products.forEach(product => {
        const currentQuantity = selectedItems.get(product.id) || 1;
        handleQuantityChange(product.id, currentQuantity);
      });
    } else {
      products.forEach(product => {
        handleQuantityChange(product.id, 0);
      });
    }
  };

  // Kiểm tra tất cả sản phẩm có được chọn hay không
  const allSelected = products.length > 0 && products.every(p => selectedItems.has(p.id));
  // Kiểm tra có ít nhất 1 sản phẩm được chọn
  const someSelected = products.some(p => selectedItems.has(p.id)) && !allSelected;

  // Cấu hình các cột cho bảng sản phẩm
  const columns = [
    {
      key: 'select',
      title: 'Chọn',
      render: (_value: any, item: ProductWithInventory) => (
        <Checkbox
          checked={selectedItems.has(item.id)}
          onChange={(checked) => handleCheckboxChange(item.id, checked)}
          size="sm"
        />
      ),
      width: '60px',
      align: 'center' as const,
    },
    {
      key: 'product_name',
      title: 'Tên sản phẩm',
      render: (value: string) => <div className="font-medium text-gray-900 truncate">{value}</div>,
    },
    {
      key: 'price',
      title: 'Giá',
      render: (value: string) => <span className="font-semibold text-gray-900">{formatCurrency(parseFloat(value))}</span>,
      width: '120px',
    },
    {
      key: 'quantity',
      title: 'Tồn kho',
      render: (value: number) => (
        <span className={`font-medium ${value > 0 ? 'text-green-600' : 'text-red-600'}`}>{value || 0}</span>
      ),
      width: '100px',
    },
    {
      key: 'selected_quantity',
      title: 'Số lượng',
      render: (_value: any, item: ProductWithInventory) => {
        const isSelected = selectedItems.has(item.id);
        const currentQuantity = selectedItems.get(item.id) || 1;
        const maxQuantity = item.inventory_quantity || 0;

        if (!isSelected) return <div className="text-center text-gray-400 text-sm">Chưa chọn</div>;

        return (
          <QuantityInput
            value={currentQuantity}
            onChange={(qty) => handleQuantityChange(item.id, qty)}
            min={1}
            max={maxQuantity}
            size="sm"
            showButtons
          />
        );
      },
      width: '80px',
      align: 'center' as const,
    },
  ];

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Chọn sản phẩm" size="xl">
      <div className="space-y-4">
        {/* Thông tin chi nhánh */}
        {branchId && (
          <div className="bg-blue-50 p-3 rounded-lg text-blue-800 text-sm">
            Hiển thị sản phẩm của chi nhánh đã chọn
          </div>
        )}

        {/* Checkbox chọn tất cả */}
        <div className="flex items-center gap-2 mb-3">
          <Checkbox
            checked={allSelected}
            indeterminate={someSelected}
            onChange={handleSelectAll}
            size="sm"
          />
          <span className="text-sm text-gray-600">{allSelected ? 'Bỏ chọn tất cả' : 'Chọn tất cả'}</span>
        </div>

        {/* Bảng sản phẩm */}
        <Table data={products} columns={columns} loading={isLoading} emptyMessage="Không có sản phẩm" />

        {/* Tổng hợp số lượng và nút thêm vào đơn hàng */}
        {selectedCount > 0 && (
          <div className="bg-green-50 p-4 rounded-lg border border-green-200">
            <div className="flex items-center justify-between">
              <div className="text-sm text-green-800">
                <div className="font-medium">Đã chọn {selectedCount} sản phẩm ({totalItems} sản phẩm)</div>
                <div className="text-xs mt-1">
                  Tổng giá trị: {formatCurrency(
                    Array.from(selectedItems.entries()).reduce((sum, [productId, quantity]) => {
                      const product = products.find(p => p.id === productId);
                      return sum + (product ? parseFloat(product.price) * quantity : 0);
                    }, 0)
                  )}
                </div>
              </div>
              <Button onClick={() => { handleAddSelected(); onClose(); }} disabled={selectedCount === 0} size="lg">
                Thêm vào đơn hàng ({selectedCount})
              </Button>
            </div>
          </div>
        )}
      </div>
    </Modal>
  );
};

export default ProductSelectionModal;
