import { useState, useCallback, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { validationSchemas, OrderCreateFormData, OrderProductData } from '../validations';
import { useBranches, useProductsByBranch, useCreateOrder } from './queries';
import { toast } from 'react-hot-toast';

/**
 * Custom Hooks for Business Logic
 * Reusable hooks that encapsulate complex business logic
 */

// ===== ORDER CREATION HOOK =====

/**
 * Hook for managing order creation form and logic
 */
export const useOrderCreation = () => {
  // Form setup with validation
  const form = useForm<OrderCreateFormData>({
    resolver: yupResolver(validationSchemas.orderCreate) as any,
    defaultValues: {
      user_id: '',
      branch_id: '',
      note: '',
      street: '',
      ward: '',
      district: '',
      city: '',
      country: 'VN',
      zipcode: '',
      products: [],
    },
    mode: 'onBlur',
  });

  // State management
  const [selectedProducts, setSelectedProducts] = useState<OrderProductData[]>([]);
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [selectedBranchId, setSelectedBranchId] = useState<string | null>(null);

  // API hooks
  const { data: branches = [], isLoading: branchesLoading } = useBranches();
  const { data: products = [], isLoading: productsLoading } = useProductsByBranch(
    selectedBranchId || '',
    !!selectedBranchId
  );
  const createOrderMutation = useCreateOrder();

  // Computed values
  const watchedBranchId = form.watch('branch_id');
  const totalAmount = useMemo(() => {
    return selectedProducts.reduce((total, product) => total + (product.price * product.quantity), 0);
  }, [selectedProducts]);

  // Event handlers
  const handleBranchChange = useCallback((value: string | number | null) => {
    const branchId = value ? String(value) : null;
    form.setValue('branch_id', branchId || '');
    setSelectedBranchId(branchId);

    // Clear selected products when branch changes
    if (branchId !== selectedBranchId) {
      setSelectedProducts([]);
      form.setValue('products', []);
    }
  }, [form, selectedBranchId]);

  const handleAddProducts = useCallback((newProducts: OrderProductData[]) => {
    const updatedProducts = [...selectedProducts];

    newProducts.forEach(newProduct => {
      const existingIndex = updatedProducts.findIndex(
        p => p.product_id === newProduct.product_id
      );

      if (existingIndex >= 0) {
        updatedProducts[existingIndex].quantity += newProduct.quantity;
      } else {
        updatedProducts.push(newProduct);
      }
    });

    setSelectedProducts(updatedProducts);
    form.setValue('products', updatedProducts);
  }, [selectedProducts, form]);

  const handleRemoveProduct = useCallback((productId: string) => {
    const updatedProducts = selectedProducts.filter(p => p.product_id !== productId);
    setSelectedProducts(updatedProducts);
    form.setValue('products', updatedProducts);
  }, [selectedProducts, form]);

  const handleUpdateQuantity = useCallback((productId: string, quantity: number) => {
    if (quantity <= 0) {
      handleRemoveProduct(productId);
      return;
    }

    const updatedProducts = selectedProducts.map(p =>
      p.product_id === productId ? { ...p, quantity } : p
    );
    setSelectedProducts(updatedProducts);
    form.setValue('products', updatedProducts);
  }, [selectedProducts, form, handleRemoveProduct]);

  const handleSubmit = useCallback(async (data: OrderCreateFormData) => {
    if (selectedProducts.length === 0) {
      toast.error('Vui lòng chọn ít nhất một sản phẩm');
      return;
    }

    try {
      await createOrderMutation.mutateAsync({
        ...data,
        note: data.note || '',
        products: selectedProducts,
      });

      // Reset form after successful submission
      form.reset();
      setSelectedProducts([]);
      setSelectedBranchId(null);
      setIsProductModalOpen(false);
    } catch (error) {
      // Error is handled by the mutation hook
      console.error('Order creation failed:', error);
    }
  }, [selectedProducts, totalAmount, createOrderMutation, form]);

  return {
    // Form
    form,

    // State
    selectedProducts,
    isProductModalOpen,
    selectedBranchId,

    // Data
    branches,
    products,

    // Loading states
    branchesLoading,
    productsLoading,
    isSubmitting: createOrderMutation.isPending,

    // Computed values
    totalAmount,

    // Actions
    handleBranchChange,
    handleAddProducts,
    handleRemoveProduct,
    handleUpdateQuantity,
    handleSubmit,
    setIsProductModalOpen,
  };
};

// ===== PRODUCT SELECTION HOOK =====

/**
 * Hook for managing product selection in modal
 */
export const useProductSelection = (
  branchId: string | null, // ID chi nhánh để lấy sản phẩm
  selectedProducts: OrderProductData[], // Danh sách sản phẩm đã chọn trước đó
  onAddProducts: (products: OrderProductData[]) => void // Callback khi thêm sản phẩm
) => {
  // State quản lý các sản phẩm đang được chọn và số lượng tương ứng
  // Map<productId, quantity>
  const [selectedItems, setSelectedItems] = useState<Map<string, number>>(new Map());

  // State lưu từ khóa search (nếu có search/filter)
  const [searchTerm, setSearchTerm] = useState('');

  // Lấy danh sách sản phẩm theo chi nhánh
  // Sử dụng hook custom `useProductsByBranch` (giả sử trả về {data, isLoading})
  const { data: products = [], isLoading } = useProductsByBranch(branchId || '', !!branchId);

  /**
   * Lọc sản phẩm dựa trên searchTerm
   * Nếu không có searchTerm thì trả về tất cả sản phẩm
   * Nếu có searchTerm, lọc theo tên sản phẩm hoặc SKU
   */
  const filteredProducts = useMemo(() => {
    if (!searchTerm) return products;

    return products.filter(product =>
      product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.sku.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [products, searchTerm]);

  /**
   * Khởi tạo Map các sản phẩm đã chọn
   * Khi modal mở hoặc dữ liệu sản phẩm load xong, gọi hook này để đồng bộ
   * Map<productId, quantity>
   */
  const initializeSelectedItems = useCallback(() => {
    const initialSelected = new Map<string, number>();
    selectedProducts.forEach(item => {
      initialSelected.set(item.product_id, item.quantity);
    });
    setSelectedItems(initialSelected);
  }, [selectedProducts]);

  /**
   * Xử lý thay đổi số lượng sản phẩm
   * - Tìm sản phẩm theo productId
   * - Clamp quantity: 0 <= quantity <= inventory_quantity
   * - Nếu quantity = 0 → xóa khỏi Map
   * - Ngược lại → cập nhật Map
   */
  const handleQuantityChange = useCallback((productId: string, quantity: number) => {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const maxQuantity = product.inventory_quantity || 0;
    const clampedQuantity = Math.max(0, Math.min(quantity, maxQuantity));

    setSelectedItems(prev => {
      const newMap = new Map(prev);
      if (clampedQuantity === 0) {
        newMap.delete(productId); // Xóa sản phẩm nếu quantity = 0
      } else {
        newMap.set(productId, clampedQuantity); // Cập nhật số lượng
      }
      return newMap;
    });
  }, [products]);

  /**
   * Xử lý nút "Thêm vào đơn hàng"
   * - Lọc các sản phẩm đang được chọn trong Map
   * - Tạo mảng OrderProductData để trả về callback onAddProducts
   * - Reset selectedItems và searchTerm sau khi thêm
   */
  const handleAddSelected = useCallback(() => {
    const newProducts: OrderProductData[] = [];

    selectedItems.forEach((quantity, productId) => {
      const product = products.find(p => p.id === productId);
      if (product) {
        newProducts.push({
          product_id: productId,
          quantity,
          price: parseFloat(product.price),
          product_name: product.name,
          sku: product.sku,
        });
      }
    });

    onAddProducts(newProducts); // Truyền sản phẩm đã chọn ra ngoài
    setSelectedItems(new Map()); // Reset Map
    setSearchTerm(''); // Reset searchTerm
  }, [selectedItems, products, onAddProducts]);

  /**
   * Computed values
   * - selectedCount: số lượng sản phẩm đang được chọn (Map.size)
   * - totalItems: tổng số lượng tất cả sản phẩm đang chọn
   */
  const selectedCount = selectedItems.size;
  const totalItems = Array.from(selectedItems.values()).reduce((sum, qty) => sum + qty, 0);

  // Trả về các giá trị và action để component sử dụng
  return {
    // Dữ liệu
    products: filteredProducts,
    selectedItems,
    searchTerm,

    // Loading
    isLoading,

    // Giá trị tính toán
    selectedCount,
    totalItems,

    // Actions
    setSearchTerm, // Thay đổi từ khóa tìm kiếm
    handleQuantityChange, // Thay đổi số lượng sản phẩm
    handleAddSelected, // Thêm sản phẩm vào đơn hàng
    initializeSelectedItems, // Khởi tạo Map sản phẩm đã chọn
  };
};


// ===== DEBOUNCED SEARCH HOOK =====

/**
 * Hook for debounced search functionality
 */
export const useDebouncedSearch = (value: string, delay: number = 300) => {
  const [debouncedValue, setDebouncedValue] = useState(value);

  const debounce = useCallback((func: Function, wait: number) => {
    let timeout: NodeJS.Timeout;
    return (...args: any[]) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => func.apply(null, args), wait);
    };
  }, []);

  const debouncedSetValue = useMemo(
    () => debounce((value: string) => setDebouncedValue(value), delay),
    [debounce, delay]
  );

  const setValue = useCallback((value: string) => {
    debouncedSetValue(value);
  }, [debouncedSetValue]);

  return { debouncedValue, setValue };
};

// ===== FORM VALIDATION HOOK =====

/**
 * Hook for enhanced form validation
 */
export const useFormValidation = <T extends Record<string, any>>(
  schema: any,
  defaultValues: T
) => {
  const form = useForm<T>({
    resolver: yupResolver(schema) as any,
    defaultValues: defaultValues as any,
    mode: 'onBlur',
  });

  const validateField = useCallback(async (fieldName: keyof T) => {
    try {
      await form.trigger(fieldName as any);
    } catch (error) {
      console.error(`Validation error for field ${String(fieldName)}:`, error);
    }
  }, [form]);

  const validateForm = useCallback(async () => {
    try {
      return await form.trigger();
    } catch (error) {
      console.error('Form validation error:', error);
      return false;
    }
  }, [form]);

  return {
    form,
    validateField,
    validateForm,
    isValid: form.formState.isValid,
    errors: form.formState.errors,
  };
};