import React from 'react';
import Button from '../ui/Button';
import QuantityInput from '../ui/QuantityInput';
import { OrderProductData } from '../../types';
import { formatCurrency } from '../../utils';

/**
 * Props interface cho SelectedProductsList
 */
interface SelectedProductsListProps {
  /** Danh sách sản phẩm đã chọn */
  products: OrderProductData[];
  /** Callback khi xóa sản phẩm */
  onRemoveProduct: (productId: string) => void;
  /** Callback khi cập nhật số lượng sản phẩm */
  onUpdateQuantity: (productId: string, quantity: number) => void;
  /** Có hiển thị tổng tiền không */
  showTotal?: boolean;
  /** Có cho phép chỉnh sửa không */
  editable?: boolean;
}

/**
 * Component SelectedProductsList - Hiển thị danh sách sản phẩm đã chọn
 * 
 * Tính năng:
 * - Hiển thị danh sách sản phẩm đã chọn với thông tin chi tiết
 * - Cho phép điều chỉnh số lượng và xóa sản phẩm
 * - Tính tổng tiền tự động
 * - Empty state khi chưa có sản phẩm
 * - Responsive design
 */
const SelectedProductsList: React.FC<SelectedProductsListProps> = ({
  products,
  onRemoveProduct,
  onUpdateQuantity,
  showTotal = true,
  editable = true,
}) => {
  // ===== COMPUTED VALUES =====
  /**
   * Tính tổng tiền của tất cả sản phẩm đã chọn
   */
  const calculateTotal = (): number => {
    return products.reduce((total, product) => total + (product.price * product.quantity), 0);
  };

  /**
   * Tính tổng số lượng sản phẩm
   */
  const calculateTotalQuantity = (): number => {
    return products.reduce((total, product) => total + product.quantity, 0);
  };

  // ===== RENDER =====
  /** Empty state khi chưa có sản phẩm nào được chọn */
  if (products.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
        <div className="text-center text-gray-500">
          <div className="w-16 h-16 mx-auto mb-4 bg-gray-100 rounded-full flex items-center justify-center">
            <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
            </svg>
          </div>
          <h3 className="text-lg font-medium text-gray-900 mb-2">Chưa có sản phẩm nào</h3>
          <p className="text-sm text-gray-600">
            Nhấn <strong>"Chọn sản phẩm"</strong> để thêm sản phẩm vào đơn hàng
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
      {/* Header */}
      <div className="p-4 border-b border-gray-200 bg-gray-50">
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold text-gray-900">
            Sản phẩm đã chọn
          </h3>
          <div className="text-sm text-gray-600">
            {products.length} sản phẩm • {calculateTotalQuantity()} đơn vị
          </div>
        </div>
      </div>
      
      {/* Products List */}
      <div className="divide-y divide-gray-200 max-h-96 overflow-y-auto">
        {products.map((product) => (
          <div key={product.product_id} className="p-4 hover:bg-gray-50 transition-colors">
            <div className="flex items-start gap-3">
              {/* Product Info */}
              <div className="flex-1 min-w-0">
                <h4 className="text-sm font-medium text-gray-900 truncate">
                  {product.product_name}
                </h4>
                <p className="text-xs text-gray-500 mt-1">
                  SKU: {product.sku}
                </p>
                <div className="flex items-center gap-4 mt-2">
                  <span className="text-sm text-gray-600">
                    Giá: <span className="font-medium">{formatCurrency(product.price)}</span>
                  </span>
                  <span className="text-sm text-gray-600">
                    Thành tiền: <span className="font-semibold text-primary-600">
                      {formatCurrency(product.price * product.quantity)}
                    </span>
                  </span>
                </div>
              </div>
              
              {/* Quantity Controls & Remove Button */}
              {editable && (
                <div className="flex items-center gap-3">
                  {/* Quantity Input */}
                  <div className="flex flex-col items-center gap-1">
                    <label className="text-xs text-gray-500">Số lượng</label>
                    <QuantityInput
                      value={product.quantity}
                      onChange={(quantity) => onUpdateQuantity(product.product_id, quantity)}
                      min={1}
                      max={9999}
                      size="sm"
                      showButtons={true}
                    />
                  </div>
                  
                  {/* Remove Button */}
                  <Button
                    variant="danger"
                    size="sm"
                    onClick={() => onRemoveProduct(product.product_id)}
                    title="Xóa sản phẩm"
                    className="mt-6"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </Button>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
      
      {/* Total Summary */}
      {showTotal && (
        <div className="p-4 bg-gray-50 border-t border-gray-200">
          <div className="space-y-2">
            {/* Subtotal */}
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-600">Tạm tính:</span>
              <span className="font-medium">{formatCurrency(calculateTotal())}</span>
            </div>
            
            {/* Tax (if applicable) */}
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-600">Thuế VAT (10%):</span>
              <span className="font-medium">{formatCurrency(calculateTotal() * 0.1)}</span>
            </div>
            
            {/* Divider */}
            <div className="border-t border-gray-300"></div>
            
            {/* Total */}
            <div className="flex items-center justify-between">
              <span className="text-lg font-semibold text-gray-900">Tổng cộng:</span>
              <span className="text-xl font-bold text-primary-600">
                {formatCurrency(calculateTotal() * 1.1)}
              </span>
            </div>
            
            {/* Summary */}
            <div className="text-xs text-gray-500 text-center">
              Bao gồm {products.length} sản phẩm • {calculateTotalQuantity()} đơn vị
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SelectedProductsList;
