import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { queryKeys, queryOptions } from '../lib/queryClient';
import { apiEndpoints } from '../services/api';
import { toast } from 'react-hot-toast';
import { SUCCESS_MESSAGES, ERROR_MESSAGES } from '../constants';
import { BranchFormData, ProductFormData, OrderCreateFormData, Order } from '../types';

/**
 * React Query Hooks
 * Custom hooks for data fetching and mutations with proper error handling
 */

// ===== BRANCHES HOOKS =====

/**
 * Hook to fetch all branches
 */
export const useBranches = (enabled = true) => {
  return useQuery({
    ...queryOptions.list(
      queryKeys.branches.lists(),
      apiEndpoints.branches.list,
      { enabled }
    ),
  });
};

/**
 * Hook to fetch a single branch
 */
export const useBranch = (id: string, enabled = true) => {
  return useQuery({
    ...queryOptions.detail(
      queryKeys.branches.detail(id),
      () => apiEndpoints.branches.detail(id),
      { enabled: enabled && !!id }
    ),
  });
};

/**
 * Hook to create a new branch
 */
export const useCreateBranch = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: apiEndpoints.branches.create,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.branches.all });
      toast.success(SUCCESS_MESSAGES.BRANCH_CREATED);
    },
    onError: (error: Error) => {
      toast.error(error.message || ERROR_MESSAGES.UNKNOWN_ERROR);
    },
  });
};

/**
 * Hook to update a branch
 */
export const useUpdateBranch = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: Partial<BranchFormData> }) =>
      apiEndpoints.branches.update(id, data),
    onSuccess: (_, { id }) => {
      queryClient.invalidateQueries({ queryKey: queryKeys.branches.all });
      queryClient.invalidateQueries({ queryKey: queryKeys.branches.detail(id) });
      toast.success(SUCCESS_MESSAGES.BRANCH_UPDATED);
    },
    onError: (error: Error) => {
      toast.error(error.message || ERROR_MESSAGES.UNKNOWN_ERROR);
    },
  });
};

/**
 * Hook to delete a branch
 */
export const useDeleteBranch = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: apiEndpoints.branches.delete,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.branches.all });
      toast.success(SUCCESS_MESSAGES.BRANCH_DELETED);
    },
    onError: (error: Error) => {
      toast.error(error.message || ERROR_MESSAGES.UNKNOWN_ERROR);
    },
  });
};

