// ===== DASHBOARD HOOKS =====

/**
 * Hook to fetch dashboard stats
 */
export const useDashboardStats = (enabled = true) => {
  return useQuery({
    ...queryOptions.list(
      queryKeys.dashboard.stats(),
      apiEndpoints.dashboard.stats,
      { enabled, staleTime: 2 * 60 * 1000 } // 2 minutes for dashboard data
    ),
  });
};

/**
 * Hook to fetch revenue chart data
 */
export const useRevenueChart = (enabled = true) => {
  return useQuery({
    ...queryOptions.list(
      queryKeys.dashboard.chart('revenue'),
      apiEndpoints.dashboard.revenueChart,
      { enabled, staleTime: 5 * 60 * 1000 } // 5 minutes for chart data
    ),
  });
};

