import React from 'react';
import { useOrderCreation } from '../../hooks';
import Input from '../../components/ui/Input';
import Button from '../../components/ui/Button';
import DropdownSelect from '../../components/ui/DropdownSelect';
import ProductSelectionModal from '../../components/modals/ProductSelectionModal';
import SelectedProductsList from '../../components/lists/SelectedProductsList';

/**
 * Component OrdersCreate - Trang tạo đơn hàng mới với React Query và Toast
 * 
 * Tính năng chính:
 * - Form nhập thông tin đơn hàng và địa chỉ giao hàng
 * - Chọn chi nhánh từ dropdown với loading state
 * - Chọn sản phẩm từ chi nhánh đã chọn (qua modal)
 * - Hiển thị danh sách sản phẩm đã chọn bên phải
 * - Validation form với Yup và React Hook Form
 * - Toast notifications cho feedback
 * - React Query cho data management
 * 
 * Layout: 2 cột responsive (form trái, danh sách sản phẩm phải)
 */
const OrdersCreate: React.FC = () => {
  const {
    // Form
    form,
    
    // State
    selectedProducts,
    isProductModalOpen,
    selectedBranchId,
    
    // Data
    branches,
    products,
    
    // Loading states
    branchesLoading,
    productsLoading,
    isSubmitting,
    
    // Computed values
    totalAmount,
    
    // Actions
    handleBranchChange,
    handleAddProducts,
    handleRemoveProduct,
    handleUpdateQuantity,
    handleSubmit,
    setIsProductModalOpen,
  } = useOrderCreation();

  const { register, handleSubmit: formHandleSubmit, formState: { errors } } = form;

  return (
    <div className="p-6">
        {/* Page Header */}
        <div className="mb-6">
          <h1 className="text-2xl font-bold text-gray-900">Tạo đơn hàng mới</h1>
          <p className="text-gray-600 mt-1">Nhập thông tin để tạo đơn hàng mới</p>
        </div>

        {/* Main Content Layout - 2 columns responsive */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* LEFT COLUMN: Order Form */}
          <div className="space-y-6">
            <form onSubmit={formHandleSubmit(handleSubmit)} className="space-y-6">
              {/* Order Information Section */}
              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <h2 className="text-lg font-semibold text-gray-900 mb-4">Thông tin đơn hàng</h2>
                
                <div className="space-y-4">
                  {/* Customer ID Field */}
                  <div>
                    <Input
                      label="ID Khách hàng"
                      {...register('user_id')}
                      error={errors.user_id?.message}
                      placeholder="Nhập ID khách hàng"
                      disabled={isSubmitting}
                    />
                  </div>

                  {/* Branch Selection Dropdown */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Chi nhánh *
                    </label>
                    <DropdownSelect
                      data={branches}
                      value={selectedBranchId}
                      onChange={handleBranchChange}
                      placeholder="Chọn chi nhánh"
                      labelKey="name"
                      valueKey="id"
                      defaultOptionLabel="Chọn chi nhánh"
                      loading={branchesLoading}
                      disabled={branchesLoading || isSubmitting}
                    />
                    {errors.branch_id && (
                      <p className="mt-1 text-sm text-red-600">{errors.branch_id.message}</p>
                    )}
                    {branchesLoading && (
                      <p className="mt-1 text-sm text-blue-600">Đang tải danh sách chi nhánh...</p>
                    )}
                  </div>

                  {/* Order Note Field */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Ghi chú
                    </label>
                    <textarea
                      {...register('note')}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent disabled:bg-gray-50 disabled:text-gray-500"
                      rows={3}
                      placeholder="Nhập ghi chú cho đơn hàng"
                      disabled={isSubmitting}
                    />
                  </div>
                </div>
              </div>

              {/* Shipping Address Section */}
              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <h2 className="text-lg font-semibold text-gray-900 mb-4">Thông tin địa chỉ giao hàng</h2>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {/* Street Address */}
                  <div>
                    <Input
                      label="Đường/Phố"
                      {...register('street')}
                      error={errors.street?.message}
                      placeholder="Nhập địa chỉ đường/phố"
                      disabled={isSubmitting}
                    />
                  </div>

                  {/* Ward */}
                  <div>
                    <Input
                      label="Phường/Xã"
                      {...register('ward')}
                      error={errors.ward?.message}
                      placeholder="Nhập phường/xã"
                      disabled={isSubmitting}
                    />
                  </div>

                  {/* District */}
                  <div>
                    <Input
                      label="Quận/Huyện"
                      {...register('district')}
                      error={errors.district?.message}
                      placeholder="Nhập quận/huyện"
                      disabled={isSubmitting}
                    />
                  </div>

                  {/* City */}
                  <div>
                    <Input
                      label="Thành phố"
                      {...register('city')}
                      error={errors.city?.message}
                      placeholder="Nhập thành phố"
                      disabled={isSubmitting}
                    />
                  </div>

                  {/* Country */}
                  <div>
                    <Input
                      label="Quốc gia"
                      {...register('country')}
                      error={errors.country?.message}
                      placeholder="Nhập quốc gia"
                      disabled={isSubmitting}
                    />
                  </div>

                  {/* Zip Code */}
                  <div>
                    <Input
                      label="Mã bưu điện"
                      {...register('zipcode')}
                      error={errors.zipcode?.message}
                      placeholder="Nhập mã bưu điện"
                      disabled={isSubmitting}
                    />
                  </div>
                </div>
              </div>

              {/* Product Selection Section */}
              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <h2 className="text-lg font-semibold text-gray-900">Sản phẩm</h2>
                    <p className="text-sm text-gray-600 mt-1">
                      Chọn sản phẩm từ chi nhánh đã chọn
                    </p>
                  </div>
                  <Button
                    type="button"
                    onClick={() => setIsProductModalOpen(true)}
                    disabled={!selectedBranchId || branchesLoading || isSubmitting}
                    variant="outline"
                    size="lg"
                  >
                    <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                    </svg>
                    Chọn sản phẩm
                  </Button>
                </div>
                
                {/* Branch Selection Warning */}
                {!selectedBranchId && (
                  <div className="mt-3 p-3 bg-amber-50 border border-amber-200 rounded-lg">
                    <p className="text-sm text-amber-800">
                      <svg className="w-4 h-4 inline mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
                      </svg>
                      Vui lòng chọn chi nhánh trước khi chọn sản phẩm
                    </p>
                  </div>
                )}

                {branchesLoading && (
                  <div className="mt-3 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                    <p className="text-sm text-blue-800">
                      <svg className="w-4 h-4 inline mr-1 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                      </svg>
                      Đang tải danh sách chi nhánh...
                    </p>
                  </div>
                )}
              </div>

              {/* Form Submit Button */}
              <div className="flex justify-end">
                <Button
                  type="submit"
                  isLoading={isSubmitting}
                  disabled={selectedProducts.length === 0 || branchesLoading}
                  size="lg"
                >
                  {isSubmitting ? 'Đang tạo đơn hàng...' : 'Tạo đơn hàng'}
                </Button>
              </div>
            </form>
          </div>

          {/* RIGHT COLUMN: Selected Products List */}
          <div className="lg:sticky lg:top-6 lg:h-fit">
            <SelectedProductsList
              products={selectedProducts}
              onRemoveProduct={handleRemoveProduct}
              onUpdateQuantity={handleUpdateQuantity}
              showTotal={true}
              editable={true}
            />
          </div>
        </div>

        {/* Product Selection Modal */}
        <ProductSelectionModal
          isOpen={isProductModalOpen}
          onClose={() => setIsProductModalOpen(false)}
          branchId={selectedBranchId}
          selectedProducts={selectedProducts}
          onAddProducts={handleAddProducts}
        />
    </div>
  );
};

export default OrdersCreate;